import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五百二十八章 什么是「有身」？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/528第五百二十八章 什么是「有身」.md","filePath":"meditation/巴利文大藏经/528第五百二十八章 什么是「有身」.md"}'),_={name:"meditation/巴利文大藏经/528第五百二十八章 什么是「有身」.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第五百二十八章-什么是「有身」" tabindex="-1">第五百二十八章 什么是「有身」？ <a class="header-anchor" href="#第五百二十八章-什么是「有身」" aria-label="Permalink to &quot;第五百二十八章 什么是「有身」？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部38相应15经/有身的询问经(阎浮车相应/处篇/弟子记说)</p><p>有个时候，舍利弗尊者住在摩揭陀国的那拉迦村中，有一天，外教修行人阎浮车来到舍利弗尊者的住处，他与舍利弗尊者互相问候后，就在一旁坐下，阎浮车对舍利弗尊者说：“舍利弗道友，什么被称为「有身」呢？什么是「有身」呢？”</p><p>舍利弗尊者回答：“阎浮车道友，五取蕴就被世尊称为「有身」，什么是五取蕴呢？即是：色取蕴、受取蕴、想取蕴、行取蕴、识取蕴，由物质事物、物质身体生起的烦恼就称为「色取蕴」，由感受生起的烦恼就称为「受取蕴」，由念想生起的烦恼就称为「想取蕴」，由行为生起的烦恼就称为「行取蕴」，由认识、分别、判断生起的烦恼就称为「识取蕴」。所谓「有身」简单的说就是由执着「我」，分辨「我」而生起见解、思想、念想。”</p><p>阎浮车说：“舍利弗道友，有熄灭、灭尽「有身」烦恼的修行方法吗？”</p><p>舍利弗尊者说：“阎浮车道友，有熄灭、灭尽「有身」烦恼的修行方法。修习八正道（八正道解释，见第十八章），就能熄灭、灭尽「有身」的烦恼，也即是修习正见、正志、正语、正业、正命、正方便、正念、正定，这八种正道就能熄灭、灭尽「有身」的烦恼。”</p><p>阎浮车说：“舍利弗道友，我明白了，修习八正道就能熄灭、灭尽「有身」的烦恼。八正道确实能够让人走上善道，八正道确实是善法，如果用八正道来熄灭、除灭恶行、恶语、恶念那确实已经足够了，如果用八正道来管束自己，让自己的行为、言语、念想不做恶事，让自己不放逸已经完全足够了，舍利弗道友，我已经知道了熄灭、灭尽「有身」烦恼的修行方法，非常感谢您。”</p><p>舍利弗尊者说法后，阎浮车虔诚恭敬的顶礼舍利弗尊者，随喜赞叹舍利弗尊者说法的无量功德，并按着舍利弗尊者所说的法去修行。</p>',9)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
